    example: '시각적인 별점 컨트롤이 단순 div 상태를 넘어 폼의 name=rating 값으로 제출되게 합니다.',
    codeLanguage: 'javascript', code: 'class RatingValue extends HTMLElement {\n  static formAssociated = true;\n  constructor() {\n    super();\n    this.internals = this.attachInternals();\n  }\n  set value(next) { this.internals.setFormValue(String(next)); }\n}\ncustomElements.define("rating-value", RatingValue);\n// 폼 안의 <rating-value name="rating">에 value를 전달합니다.',
