    codeLanguage: 'javascript', code: '// Service Worker: /offline.html을 배포해 두었다고 가정합니다.\nself.addEventListener("install", event => {\n  event.waitUntil(caches.open("shell-v2").then(cache => {\n    return cache.addAll(["/offline.html"]);\n  }));\n});\nself.addEventListener("activate", event => {\n  event.waitUntil((async () => {\n    await caches.delete("shell-v1");\n  })());\n});',
